const fs = require('fs');
const files = [
  'C:\\\\Users\\\\hzq00\\\\Documents\\\\Codex\\\\2026-08-23\\\\ni-j\\\\outputs\\\\HONOR_DESIRED_STATE.stage3.20260823.json',
  'C:\\\\Users\\\\hzq00\\\\Documents\\\\Codex\\\\2026-08-23\\\\ni-j\\\\outputs\\\\HONOR_DESIRED_STATE.stage3.20260823.json.bak_before_stage5_keepalive',
  'C:\\\\Users\\\\hzq00\\\\Documents\\\\Codex\\\\2026-08-23\\\\ni-j\\\\outputs\\\\HONOR_DESIRED_STATE.stage3.20260823.json.bak_before_restore_floattasks'
];
const pkgs = ['floattasks','hndockbar','dockbar','float_task','sidebar','phoneservice','keep_alive'];
function find(o, path, acc) {
  if (o == null) return;
  if (typeof o === 'string' || typeof o === 'number' || typeof o === 'boolean') {
    const s = String(o).toLowerCase();
    if (pkgs.some(p => s.includes(p))) acc.push([path, o]);
    return;
  }
  if (Array.isArray(o)) {
    o.forEach((v,i) => find(v, path+'['+i+']', acc));
    return;
  }
  if (typeof o === 'object') {
    for (const [k,v] of Object.entries(o)) {
      const kl = k.toLowerCase();
      const kp = path ? path+'.'+k : k;
      if (pkgs.some(p => kl.includes(p))) acc.push([kp, v]);
      find(v, kp, acc);
    }
  }
}
for (const f of files) {
  const obj = JSON.parse(fs.readFileSync(f,'utf8'));
  console.log('\\\\n===== '+f.split('\\\\\\\\').pop()+' =====');
  console.log('schema_version', obj.schema_version);
  console.log('device', JSON.stringify(obj.device));
  const acc=[];
  find(obj,'',acc);
  // unique paths
  const seen=new Set();
  for (const [p,v] of acc) {
    if (seen.has(p)) continue;
    seen.add(p);
    let s = typeof v === 'object' ? JSON.stringify(v) : String(v);
    if (s.length>800) s=s.slice(0,800)+'...';
    console.log(p+' => '+s);
  }
  // also dump restored_after_user_report if present
  if (obj.restored_after_user_report) {
    console.log('FULL restored_after_user_report', JSON.stringify(obj.restored_after_user_report,null,2));
  }
  if (obj.keep_alive_background) {
    console.log('FULL keep_alive_background', JSON.stringify(obj.keep_alive_background,null,2));
  }
  // check if hndockbar in any package lists
  const listKeys = Object.keys(obj).filter(k => Array.isArray(obj[k]));
  for (const k of listKeys) {
    const hits = obj[k].filter(x => {
      const blob = JSON.stringify(x).toLowerCase();
      return blob.includes('floattasks') || blob.includes('hndockbar') || blob.includes('dockbar') || blob.includes('sidebar');
    });
    if (hits.length) console.log('LIST '+k+' HITS', JSON.stringify(hits,null,2));
  }
}
\"@
"

